export function loadAcquisitionData() {
  if (itemIndex && wikiAcquisitionIndex) return Promise.resolve();
  if (loadPromise) return loadPromise;
  loadPromise = Promise.all([
    invoke('read_file_bytes', { relative: 'data/assets/data/warframe-items-acquisition.json' })
      .then((bytes) => {
        const arr = JSON.parse(new TextDecoder().decode(new Uint8Array(bytes)));
        itemIndex = new Map(arr.map((item) => [item.uniqueName, item]));
        itemNameIndex = new Map(arr.filter(i => i.name).map((item) => [item.name.toLowerCase(), item]));
        componentIndex = new Map();
        for (const item of arr) {
          for (const component of item.components || []) {
            if (component?.uniqueName && Array.isArray(component.drops) && component.drops.length > 0 && !componentIndex.has(component.uniqueName)) {
              componentIndex.set(component.uniqueName, component);
            }
          }
        }
      })
      .catch(() => {
        itemIndex = new Map();
        itemNameIndex = new Map();
        componentIndex = new Map();
      }),
    invoke('read_file_bytes', { relative: 'data/assets/data/wiki-verified-all-acquisitions.json' })
      .then((bytes) => {
        const data = JSON.parse(new TextDecoder().decode(new Uint8Array(bytes)));
        wikiAcquisitionIndex = new Map(Object.entries(data).map(([k, v]) => [k.toLowerCase().trim(), v]));
      })
      .catch(() => {
        wikiAcquisitionIndex = new Map();
      })
  ]);
  return loadPromise;
}

export function getItemDrops(uniqueName) {
  const candidates = [
    itemIndex?.get(uniqueName),
    itemIndex?.get(canonicalPath(uniqueName)),
    componentIndex?.get(uniqueName),
    componentIndex?.get(canonicalPath(uniqueName)),
  ];
  const item = candidates.find((candidate) => Array.isArray(candidate?.drops) && candidate.drops.length > 0);
  if (!item || !Array.isArray(item.drops) || item.drops.length === 0) return null;

  return [...item.drops]
    .sort((a, b) => (b.chance ?? 0) - (a.chance ?? 0))
    .map((d) => ({
      type: 'drop',
      location: d.location,
      dropType: d.type,
      rarity: d.rarity,
      chance: d.chance,
    }));
}

export function getItemRecipe(uniqueName, displayName) {
  const item = itemIndex?.get(uniqueName) || itemIndex?.get(canonicalPath(uniqueName)) || (displayName ? itemNameIndex?.get(displayName.toLowerCase().trim()) : null);
  if (!item) return null;

  const components = (item.components || []).filter(c => !/^blueprint$/i.test((c.name || '').trim()));
  const isTrulyCraftable = (item.craftable === true && components.length > 0) || components.length > 0;
  
  if (!isTrulyCraftable) return null;

  const bpComponent = (item.components || []).find(c => /^blueprint$/i.test((c.name || '').trim()));
  const bpDrops = bpComponent?.drops || [];

  return {
    craftable: true,
    buildPrice: item.buildPrice ?? null,
    buildTime: item.buildTime ?? null,
    skipBuildTimePrice: item.skipBuildTimePrice ?? null,
    consumeOnBuild: item.consumeOnBuild ?? true,
    bpCost: item.bpCost ?? null,
    blueprintCost: item.bpCost ?? null,
    blueprintDrops: bpDrops,
    marketCost: item.marketCost ?? null,
    itemCount: item.itemCount ?? 1,
    components: (item.components || []).map((c) => ({
      name: c.name,
      uniqueName: c.uniqueName,
      itemCount: c.itemCount ?? 1,
      drops: c.drops || [],
    })),
  };
}

export function getResourceLocation(name, uniqueName) {
  if (name) {
    const norm = name.trim().toLowerCase();
    if (RESOURCE_LOCATIONS[norm]) return RESOURCE_LOCATIONS[norm];
    const wf = WARFRAME_ACQUISITIONS[norm];
    if (wf?.general) return wf.general;
  }
  if (uniqueName) {
    const item = itemIndex?.get(uniqueName) || itemIndex?.get(canonicalPath(uniqueName));
    if (item?.location) return item.location;
    if (item?.name) {
      const norm = item.name.trim().toLowerCase();
      if (RESOURCE_LOCATIONS[norm]) return RESOURCE_LOCATIONS[norm];
      const wf = WARFRAME_ACQUISITIONS[norm];
      if (wf?.general) return wf.general;
    }
  }
  return null;
}

export function resolveComponentAcquisition(name, parentName) {
  if (!name) return null;
  const clean = name.trim();
  const normName = clean.toLowerCase();
  const normParent = (parentName || '').toLowerCase().trim();

  // 1. Direct open-world, planetary & verified item resource locations (O(1) hash lookup)
  if (RESOURCE_LOCATIONS[normName]) {
    return RESOURCE_LOCATIONS[normName];
  }

  // 2. Parent-specific Warframe / Weapon / Companion / Ship resolution (O(1) hash lookup)
  const wf = WARFRAME_ACQUISITIONS[normParent];
  if (wf) {
    if (normName.includes('neuroptics')) return wf.neuroptics || wf.general;
    if (normName.includes('chassis')) return wf.chassis || wf.general;
    if (normName.includes('systems')) return wf.systems || wf.general;
    if (normName.includes('blueprint')) return wf.blueprint || wf.general;
    if (normName.includes('avionics')) return wf.avionics || wf.general;
    if (normName.includes('fuselage')) return wf.fuselage || wf.general;
    if (normName.includes('engines')) return wf.engines || wf.general;
    if (normName.includes('harness') || normName.includes('wings')) return wf.general;
    if (normName.includes('casing') || normName.includes('engine') || normName.includes('capsule') || normName.includes('pod')) return wf.general;
    if (normName.includes('barrel') || normName.includes('receiver') || normName.includes('stock') || normName.includes('link')) return wf.general;
    if (normName.includes('blade') || normName.includes('handle') || normName.includes('guard') || normName.includes('hook') || normName.includes('hilt') || normName.includes('heatsink') || normName.includes('limb') || normName.includes('grip') || normName.includes('string')) return wf.general;
  }

  // 3. Full component name matching (e.g. "Zephyr Chassis" -> Tenno Lab, "Parallax Avionics" -> Zariman)
  const match = clean.match(/^(.+?)\s+(Neuroptics|Chassis|Systems|Blueprint|Avionics|Fuselage|Engines|Blade|Handle|Hilt|Barrel|Receiver|Stock|Link|String|Grip|Limb|Guard|Pouch|Stars|Casing|Engine|Capsule|Weapon Pod|Harness|Wings|Heatsink)(?:\s+Blueprint)?$/i);
  if (match) {
    const pName = match[1].toLowerCase().trim();
    const partType = match[2].toLowerCase();
    const entry = WARFRAME_ACQUISITIONS[pName];
    if (entry) {
      return entry[partType] || entry.general || null;
    }
  }

  // 4. Clan Dojo Research (O(1) hash lookup)
  const r = WIKI_RESEARCH[clean] || WIKI_RESEARCH[normName];
  if (r?.lab) {
    return `Clan Dojo (${r.lab} Research)`;
  }

  // 5. Syndicate / Pity Vendors (O(1) hash lookup)
  const v = WIKI_VENDORS[clean] || WIKI_VENDORS[normName];
  if (v?.length) {
    return `Vendor: ${v.join(', ')}`;
  }

  // 6. Direct Master general acquisition lookup
  const directWf = WARFRAME_ACQUISITIONS[normName];
  if (directWf?.general) {
    return directWf.general;
  }

  // 7. Verified Wiki Master Database (O(1) lookup across 1,598 wiki entries)
  if (wikiAcquisitionIndex?.has(normName)) {
    return wikiAcquisitionIndex.get(normName);
  }

  return null;
}

export function resolveBlueprintOrigin(displayName, resolvedRecipe) {
  if (!displayName) return null;
  const norm = displayName.toLowerCase().trim();

  // 1. Clan Dojo Research (O(1) hash lookup)
  const r = WIKI_RESEARCH[displayName] || WIKI_RESEARCH[norm];
  if (r?.lab) {
    const creditStr = resolvedRecipe?.blueprintCost ? ` (${resolvedRecipe.blueprintCost.toLocaleString()} Credits)` : '';
    return `Clan Dojo Research: ${r.lab}${creditStr}`;
  }

  // 2. Warframe & Weapon Master Registry (O(1) hash lookup)
  const wf = WARFRAME_ACQUISITIONS[norm];
  if (wf?.blueprint) {
    return `Blueprint: ${wf.blueprint}`;
  }

  // 3. Enemy / Relic Drops on Blueprint
  if (resolvedRecipe?.blueprintDrops?.length) {
    const cleaned = resolvedRecipe.blueprintDrops;
    const names = cleaned.slice(0, 4).map(d => d.relicName || d.location || 'Drop');
    const remaining = cleaned.length - names.length;
    return `Blueprint Drops: ${names.join(', ')}${remaining > 0 ? ` (+${remaining} more)` : ''}`;
  }

  // 4. Verified Market Blueprint
  if (resolvedRecipe?.blueprintCost) {
    return `Market Blueprint: ${resolvedRecipe.blueprintCost.toLocaleString()} Credits`;
  }

  // 5. Fallback to general master entry if present
  if (wf?.general) {
    return wf.general;
  }

  return null;
}

export function getIngredientDetails(ingredient, parentName) {
  if (!ingredient) return null;
  const key = ingredient.itemType;
  const item = itemIndex?.get(key) || itemIndex?.get(canonicalPath(key)) || (ingredient.name ? itemNameIndex?.get(ingredient.name.toLowerCase()) : null);
  
  const drops = getItemDrops(key) || (item?.drops?.length ? item.drops.map(d => ({ type: "drop", location: d.location, dropType: d.type, rarity: d.rarity, chance: d.chance })) : null);
  const componentAcq = resolveComponentAcquisition(ingredient.name || item?.name, parentName);

  return {
    location: item?.location || null,
    bpCost: item?.bpCost || null,
    marketCost: item?.marketCost || null,
    componentAcq: componentAcq || null,
    drops: drops || [],
  };
}

export function getWikiLink(dropIndexKey, displayName) {
  const name = displayName || dropIndexKey;
  if (!name) return { url: "https://wiki.warframe.com", isDirect: false };
  // isDirect: false means the target page was never confirmed to exist (no
  // verified per-item wiki source matched this item) - so this must be an
  // actual search query, not a guessed /w/Item_Name article slug. A guessed
  // slug for an item with no wiki page (e.g. a niche cosmetic never given
  // its own article) 404s regardless of the button being labeled "Search".
  return { url: `https://wiki.warframe.com/index.php?search=${encodeURIComponent(name.trim())}`, isDirect: false };
}

export function isCraftable(uniqueName) {
  const recipe = getItemRecipe(uniqueName);
  return !!(recipe && recipe.craftable && recipe.components && recipe.components.length > 0);
}
